from collections import Counter
def transform(grid):
    g=[row[:] for row in grid]; H,W=len(g),len(g[0])
    # learn diagonal pattern in region r>=3,c>=3
    cnt=Counter()
    for r in range(3,H):
        for c in range(3,W):
            if g[r][c]!=0: cnt[((r+c),g[r][c])]+=1
    res=defaultdict(Counter)
    for (d,v),n in cnt.items(): res[d%7][v]+=n
    diag={k:v for k in res for v in [res[k].most_common(1)[0][0]]}
    # fill zeros
    for r in range(H):
        for c in range(W):
            if g[r][c]!=0: continue
            if r>=3 and c>=3:
                g[r][c]=diag[(r+c)%7]
            else:
                # use nearest nonzero neighbors in row / column
                row_vals=[g[r][x] for x in range(W) if g[r][x]!=0]
                col_vals=[g[y][c] for y in range(H) if g[y][c]!=0]
                cr=Counter(row_vals).most_common(1)[0][0] if row_vals else None
                cc=Counter(col_vals).most_common(1)[0][0] if col_vals else None
                g[r][c]=cr if cr is not None else cc
    return g
