def transform(grid):
    g=[row[:] for row in grid]; H,W=len(g),len(g[0])
    cells=[(r,c,g[r][c]) for r in range(3,H) for c in range(3,W) if g[r][c]!=0]
    best=None
    for p in range(1,11):
        res=defaultdict(Counter)
        for r,c,v in cells: res[(r+c)%p][v]+=1
        diag={k:ct.most_common(1)[0][0] for k,ct in res.items()}
        score=sum(n for ct in res.values() for _,n in ct.most_common(1))
        if best is None or score>best[0]: best=(score,p,diag)
    _,p,diag=best
    for r in range(H):
        for c in range(W):
            if g[r][c]!=0: continue
            if r>=3 and c>=3:
                g[r][c]=diag[(r+c)%p]; continue
            if r<3:
                cand=[(abs(x-c),g[r][x]) for x in range(W) if g[r][x]!=0]
            else:
                cand=[(abs(y-r),g[y][c]) for y in range(H) if g[y][c]!=0]
            g[r][c]=min(cand)[1]
    return g
